import{_ as t,o as a,c as i,ao as s}from"./chunks/framework.Dz-3nxMo.js";const k=JSON.parse('{"title":"Instrument Formats","description":"","frontmatter":{},"headers":[],"relativePath":"formats.md","filePath":"formats.md","lastUpdated":null}'),n={name:"formats.md"};function l(r,e,d,o,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="Instrument-Formats" tabindex="-1">Instrument Formats <a class="header-anchor" href="#Instrument-Formats" aria-label="Permalink to &quot;Instrument Formats {#Instrument-Formats}&quot;">​</a></h1><p>Timekeepers reads three instrument formats natively and writes all three back out. Each has the same three-function shape:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Run reader</th><th style="text-align:left;"><code>TimeArray</code> reader</th><th style="text-align:left;">Writer</th></tr></thead><tbody><tr><td style="text-align:left;">LEMI-424</td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.read_lemi424"><code>read_lemi424</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.load_lemi424"><code>load_lemi424</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.write_lemi424"><code>write_lemi424</code></a></td></tr><tr><td style="text-align:left;">GEOMAG-02</td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.read_geomag"><code>read_geomag</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.load_geomag"><code>load_geomag</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.write_geomag"><code>write_geomag</code></a></td></tr><tr><td style="text-align:left;">Metronix ADU</td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.read_metronix"><code>read_metronix</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.load_metronix"><code>load_metronix</code></a></td><td style="text-align:left;"><a href="/Timekeepers.jl/dev/api#Timekeepers.write_metronix"><code>write_metronix</code></a></td></tr></tbody></table><p><a href="/Timekeepers.jl/dev/api#Timekeepers.read_timekeeper"><code>read_timekeeper</code></a> and <a href="/Timekeepers.jl/dev/api#Timekeepers.write_timekeeper"><code>write_timekeeper</code></a> sit in front of all three and pick the right one automatically.</p><h2 id="Component-naming" tabindex="-1">Component naming <a class="header-anchor" href="#Component-naming" aria-label="Permalink to &quot;Component naming {#Component-naming}&quot;">​</a></h2><p>Whatever the source format, channels arrive under one set of names, so the rest of the package — masking, plotting, spectra — does not care where the data came from:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Component</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Units</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:bx</code>, <code>:by</code>, <code>:bz</code></td><td style="text-align:left;">magnetic field, geographic N / E / down</td><td style="text-align:left;">nT</td></tr><tr><td style="text-align:left;"><code>:e1</code>, <code>:e2</code></td><td style="text-align:left;">electric field, dipole 1 / 2</td><td style="text-align:left;">mV/km</td></tr><tr><td style="text-align:left;"><code>:temperature_e</code>, <code>:temperature_h</code></td><td style="text-align:left;">electronics / sensor temperature</td><td style="text-align:left;">°C</td></tr><tr><td style="text-align:left;"><code>:battery</code></td><td style="text-align:left;">supply voltage</td><td style="text-align:left;">V</td></tr><tr><td style="text-align:left;"><code>:elevation</code></td><td style="text-align:left;">GPS elevation</td><td style="text-align:left;">m</td></tr></tbody></table><p><a href="/Timekeepers.jl/dev/api#Timekeepers.default_components"><code>default_components</code></a> returns the five signal channels in conventional plotting order (<code>bx, by, bz, e1, e2</code>); <a href="/Timekeepers.jl/dev/api#Timekeepers.components"><code>components</code></a> returns everything present, auxiliary channels included.</p><h2 id="LEMI-424" tabindex="-1">LEMI-424 <a class="header-anchor" href="#LEMI-424" aria-label="Permalink to &quot;LEMI-424 {#LEMI-424}&quot;">​</a></h2><p>Long-period ASCII text: one whitespace-separated record per sample, six date/time fields followed by the magnetic, electric, temperature, GPS and housekeeping columns. <a href="/Timekeepers.jl/dev/api#Timekeepers.LEMI424_COLUMNS"><code>LEMI424_COLUMNS</code></a> names all 24 fields in file order.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Timekeepers</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ta  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># straight to a TimeArray</span></span></code></pre></div><p>Real files are not always exactly 24 columns wide — firmware revisions add trailing fields, and some exports truncate them. The reader tolerates both: extra columns are ignored, and missing trailing columns come back as <code>NaN</code> rather than an error.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/short_record.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">all</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(isnan, run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channels[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:time_diff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># true when the column was absent</span></span></code></pre></div><p>Pass <code>include_aux = false</code> to skip the housekeeping channels when you only want the five signal components.</p><p>The writer reproduces the original 24-field layout. Auxiliary values are held in the <code>TimeArray</code> metadata under <code>:aux_columns</code> and written back into their own slots, so a read/write cycle is lossless:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ta </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">write_lemi424</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090_copy.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ta)</span></span></code></pre></div><p>Both writers accept either a <a href="/Timekeepers.jl/dev/api#Timekeepers.TimekeeperRun"><code>TimekeeperRun</code></a> or a <code>TimeArray</code>.</p><h3 id="Generic-LEMI-.xyz-exports" tabindex="-1">Generic LEMI <code>.xyz</code> exports <a class="header-anchor" href="#Generic-LEMI-.xyz-exports" aria-label="Permalink to &quot;Generic LEMI \`.xyz\` exports {#Generic-LEMI-.xyz-exports}&quot;">​</a></h3><p>TKApp additionally loads and writes 7-column LEMI-style exports (<code>date time Bx By Bz Ex Ey</code>) when a file has the <code>.xyz</code> extension. There is no public reader for these; open them through the app or through <a href="/Timekeepers.jl/dev/api#Timekeepers.run_tkapp"><code>run_tkapp</code></a>.</p><h2 id="GEOMAG-02" tabindex="-1">GEOMAG-02 <a class="header-anchor" href="#GEOMAG-02" aria-label="Permalink to &quot;GEOMAG-02 {#GEOMAG-02}&quot;">​</a></h2><p>ASCII text opening with a block of <code>;</code>-prefixed header lines carrying the instrument model, sampling interval and station position, then one record per sample with fractional seconds.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_geomag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/MS_26_250523000000.TXT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sampling_rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run)                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 10.0 for a 0.10 s interval</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">metadata[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:instrument_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># &quot;GEOMAG-02&quot;</span></span></code></pre></div><p>Format detection keys on the <code>GEOMAG</code> token in the header, so <a href="/Timekeepers.jl/dev/api#Timekeepers.read_timekeeper"><code>read_timekeeper</code></a> tells these apart from LEMI-424 <code>.txt</code> files without being told.</p><p>Beyond the five signal channels the reader picks up <code>:temperature_h</code> and <code>:temperature_e</code>, and <a href="/Timekeepers.jl/dev/api#Timekeepers.write_geomag"><code>write_geomag</code></a> emits the header block along with the data, so the output is readable by the same tools as the input.</p><h2 id="Metronix-ADU-ATS" tabindex="-1">Metronix ADU (ATS) <a class="header-anchor" href="#Metronix-ADU-ATS" aria-label="Permalink to &quot;Metronix ADU (ATS) {#Metronix-ADU-ATS}&quot;">​</a></h2><p>A Metronix run is a set of files in a <code>meas_*</code> directory: one <code>.ats</code> binary per channel plus an <code>.xml</code> sidecar. A <code>meas_*</code> directory can hold several runs — a 128 Hz run and 4096 Hz bursts, say — told apart by the run number (<code>R000</code>, <code>R001</code>, …) and rate in their filenames. The <code>.ats</code> header carries the sample count, sampling rate, start time as a Unix timestamp, the LSB scaling value and the channel type; the samples themselves are <code>Int32</code> counts that the reader scales by the LSB.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_metronix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/RK137/meas_2025-04-01_07-00-05&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># [:bx, :by, :bz, :e1, :e2]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sampling_rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 128.0</span></span></code></pre></div><p>Channel types map to component names through <a href="/Timekeepers.jl/dev/api#Timekeepers.METRONIX_CHANNEL_MAP"><code>METRONIX_CHANNEL_MAP</code></a> — <code>Ex → :e1</code>, <code>Ey → :e2</code>, <code>Hx → :bx</code>, <code>Hy → :by</code>, <code>Hz → :bz</code>. Unrecognised channel types are carried through under a symbol of their own name rather than dropped.</p><div class="tip custom-block"><p class="custom-block-title">Point at one run</p><p><a href="/Timekeepers.jl/dev/api#Timekeepers.read_metronix"><code>read_metronix</code></a> takes a run&#39;s <code>.xml</code>, any of its <code>.ats</code> files, or a <code>meas_*</code> directory holding a single run. A directory holding several runs is ambiguous, and the error lists them. The site directory above the <code>meas_*</code> directories is handled by <a href="/Timekeepers.jl/dev/api#Timekeepers.metronix_site_runs"><code>metronix_site_runs</code></a> and the site writers covered in <a href="./metronix">Metronix Sites</a>.</p></div><p><a href="/Timekeepers.jl/dev/api#Timekeepers.write_metronix"><code>write_metronix</code></a> writes a measurement directory back out, regenerating the XML sidecar from the template the run was read with. That template path lives in <code>run.metadata[:metronix_xml_path]</code>, so a run must have come from <a href="/Timekeepers.jl/dev/api#Timekeepers.read_metronix"><code>read_metronix</code></a> to be written as Metronix.</p><p>Because a mask usually means &quot;cut this out&quot;, Metronix has a second writer that splits rather than blanks — see <a href="./metronix">Metronix Sites</a>.</p><h2 id="What-metadata-survives" tabindex="-1">What metadata survives <a class="header-anchor" href="#What-metadata-survives" aria-label="Permalink to &quot;What metadata survives {#What-metadata-survives}&quot;">​</a></h2><p>Readers keep the run-level information a writer needs, and it is all reachable from <code>run.metadata</code> (or <code>TimeSeries.meta(ta)</code> on the <code>TimeArray</code> side):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Present for</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:sample_rate</code></td><td style="text-align:left;">all</td><td style="text-align:left;">samples per second</td></tr><tr><td style="text-align:left;"><code>:start_time</code></td><td style="text-align:left;">all</td><td style="text-align:left;">timestamp of the first sample</td></tr><tr><td style="text-align:left;"><code>:instrument_model</code></td><td style="text-align:left;">GEOMAG, Metronix</td><td style="text-align:left;">instrument identification</td></tr><tr><td style="text-align:left;"><code>:aux_columns</code></td><td style="text-align:left;">LEMI-424, GEOMAG</td><td style="text-align:left;">auxiliary column values, for lossless writes</td></tr><tr><td style="text-align:left;"><code>:site</code>, <code>:n_files</code></td><td style="text-align:left;">site loads</td><td style="text-align:left;">site name and number of runs combined</td></tr><tr><td style="text-align:left;"><code>:metronix_xml_path</code></td><td style="text-align:left;">Metronix</td><td style="text-align:left;">XML template used to regenerate the sidecar</td></tr><tr><td style="text-align:left;"><code>:metronix_prefix</code>, <code>:metronix_run_token</code>, <code>:metronix_freq_token</code></td><td style="text-align:left;">Metronix</td><td style="text-align:left;">filename tokens preserved on write</td></tr><tr><td style="text-align:left;"><code>:mask_intervals</code>, <code>:masked_samples</code></td><td style="text-align:left;">after masking</td><td style="text-align:left;">what was cut, and how much</td></tr></tbody></table>`,34)])])}const m=t(n,[["render",l]]);export{k as __pageData,m as default};
